// TASK-0041 — V1 Manual Refresh Through Incremental Apply, product acceptance in
// real WebView2. No simulated DOM, no alternate renderer, no personal data: both
// trees under test were generated by task0041-seed-proof.py and die with the
// proof root.
//
// Two phases, one REAL process restart between them (run by the .ps1):
//
//   phase 1  first Actualiser -> BASELINE_FULL, nothing invented; a second,
//            unchanged Actualiser -> INCREMENTAL, « Aucun changement détecté. »,
//            the very same revision; a batch of external mutations (create,
//            modify, delete, rename, move, a new folder with a file) -> ONE real
//            Actualiser -> INCREMENTAL with the exact summary and exactly one new
//            revision; the journal and the NEW/UNSEEN filters read through the
//            real panels; « Tout marquer vu », then a later change is unseen
//            again; an element marked seen and changed again; a whole folder
//            renamed with its descendants; Reconstruire -> EXPLICIT_REBUILD_FULL
//            with journal and seen state intact; the next Actualiser is
//            INCREMENTAL again; a second brain refreshed alongside, untouched by
//            the first.
//   phase 2  after the real restart: journal, seen state and revision identical;
//            a cold Actualiser is INCREMENTAL and quiet; one more change is
//            applied incrementally.
//
// Which path applied each scan is read from the REAL `map_refresh` /
// `map_rebuild` answer that the real button click provoked (a probe on the
// page's own `invoke`, recording only closed fields) and from the discreet label
// the product now shows. Every filesystem change is made by THIS script directly
// on disk, outside the product process, between two real clicks.
import assert from "node:assert/strict";
import { readFile, writeFile, rm, rename, mkdir } from "node:fs/promises";
import { setTimeout as pause } from "node:timers/promises";
import { join } from "node:path";

const port = Number(process.argv[2]);
const variant = process.argv[3];
const phase = Number(process.argv[4]);
assert(/^task0041-[a-f0-9]+$/.test(variant));
assert(phase === 1 || phase === 2);

const seed = JSON.parse(
  (
    await new Promise((resolve, reject) => {
      let text = "";
      process.stdin.setEncoding("utf8");
      process.stdin.on("data", (c) => (text += c));
      process.stdin.on("end", () => resolve(text));
      process.stdin.on("error", reject);
    })
  ).replace(/^﻿/, ""), // PowerShell's pipe prepends a UTF-8 BOM.
);
const { brainId, secondBrainId, absolutePath, secondAbsolutePath } = seed;
const proofRoot = join(".filetopo-sandbox", variant);
const root = absolutePath; // real absolute paths, used only by THIS script's own fs calls — never sent into the page.
const secondRoot = secondAbsolutePath;

let target;
for (let n = 0; n < 100; n++) {
  try {
    const pages = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
    target = pages.find((p) => p.type === "page");
    if (target) break;
  } catch {}
  await pause(200);
}
assert(target, "WebView2 CDP page unavailable");
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => {
  ws.addEventListener("open", resolve, { once: true });
  ws.addEventListener("error", reject, { once: true });
});
let serial = 0;
const pending = new Map();
const fatal = [];
// The REAL map_refresh / map_rebuild round trips, observed on the wire (Tauri's
// IPC requests) through CDP's Network domain: which command was sent, when it
// finished, and whether it succeeded. The response body of a custom-protocol
// request is not retrievable through CDP, so the closed report fields (mode,
// summary, revision) are read from the product's own UI, which renders exactly
// what those reports carried.
const wireRequests = new Map();
const wireStatus = new Map();
const wireCalls = [];
ws.addEventListener("message", ({ data }) => {
  const event = JSON.parse(data);
  if (event.method === "Network.requestWillBeSent") {
    const url = event.params.request.url;
    const m = /\/(map_refresh|map_rebuild)(?:[?#].*)?$/.exec(url);
    if (m && /ipc/.test(url)) wireRequests.set(event.params.requestId, m[1]);
  } else if (event.method === "Network.responseReceived" && wireRequests.has(event.params.requestId)) {
    wireStatus.set(event.params.requestId, event.params.response.status);
  } else if (event.method === "Network.loadingFinished" && wireRequests.has(event.params.requestId)) {
    const id = event.params.requestId;
    wireCalls.push({ command: wireRequests.get(id), ok: (wireStatus.get(id) ?? 200) === 200 });
    wireRequests.delete(id);
  } else if (event.method === "Network.loadingFailed" && wireRequests.has(event.params.requestId)) {
    wireCalls.push({ command: wireRequests.get(event.params.requestId), ok: false });
    wireRequests.delete(event.params.requestId);
  }
  if (event.id) {
    const p = pending.get(event.id);
    pending.delete(event.id);
    if (event.error) p?.reject(new Error(JSON.stringify(event.error)));
    else p?.resolve(event.result);
  } else if (
    event.method === "Runtime.exceptionThrown" ||
    (event.method === "Log.entryAdded" && event.params.entry.level === "error")
  ) {
    fatal.push(event);
  }
});
const send = (method, params = {}) =>
  new Promise((resolve, reject) => {
    const id = ++serial;
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });
async function evaluate(expression) {
  const r = await send("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) {
    throw new Error(
      r.exceptionDetails.exception?.description ??
        r.exceptionDetails.exception?.value ??
        JSON.stringify(r.exceptionDetails),
    );
  }
  return r.result.value;
}
async function until(expression, limit = 240000) {
  const start = Date.now();
  while (Date.now() - start < limit) {
    if (await evaluate(expression)) return;
    await pause(100);
  }
  throw new Error(`timeout: ${expression}`);
}
const exposedPayloads = [];
const invoke = async (command, args = {}) => {
  exposedPayloads.push(JSON.stringify(args));
  const result = await evaluate(
    `window.__TAURI_INTERNALS__.invoke(${JSON.stringify(command)},${JSON.stringify(args)})`,
  );
  exposedPayloads.push(JSON.stringify(result ?? null));
  return result;
};
await send("Runtime.enable");
await send("Log.enable");
await send("Page.enable");
await send("Network.enable", { maxTotalBufferSize: 64 * 1024 * 1024, maxResourceBufferSize: 16 * 1024 * 1024 });

async function key(k) {
  const vk = k === "Enter" ? 13 : 0;
  await send("Input.dispatchKeyEvent", {
    type: "keyDown",
    key: k,
    code: k,
    windowsVirtualKeyCode: vk,
    nativeVirtualKeyCode: vk,
    ...(k === "Enter" ? { text: "\r", unmodifiedText: "\r" } : {}),
  });
  await send("Input.dispatchKeyEvent", { type: "keyUp", key: k, code: k, windowsVirtualKeyCode: vk, nativeVirtualKeyCode: vk });
  await pause(120);
}
async function activate(selector) {
  const found = await evaluate(`!!document.querySelector(${JSON.stringify(selector)})`);
  assert(found, `activate: selector not found — ${selector}`);
  await evaluate(`document.querySelector(${JSON.stringify(selector)}).focus()`);
  await key("Enter");
}
const jargon = [
  "stable_key",
  "stableKey",
  "identity_provenance",
  "identityProvenance",
  "SYS1:",
  "PFv1:",
  "PATH_FALLBACK",
  "fileId",
  "file_id",
  "volumeSerial",
  "volume_serial",
];
function assertNoJargon(text, where) {
  for (const word of jargon) assert(!text.includes(word), `internal identity jargon "${word}" leaked into ${where}`);
}
function assertNoPathLeak(text, where) {
  for (const path of [root, secondRoot]) {
    const escaped = path.split("\\").join("\\\\");
    assert(!text.includes(path) && !text.includes(escaped), `absolute path leaked into ${where}`);
  }
}

// ---- the wire probe (see above) -----------------------------------------------
const probeCount = async () => wireCalls.length;
const probeCalls = async (from) => wireCalls.slice(from);

async function assertConfidential() {
  const bodyText = await evaluate("document.body.textContent");
  assertNoPathLeak(bodyText, "page body text");
  assertNoJargon(bodyText, "page body text");
  for (const payload of exposedPayloads) {
    assertNoPathLeak(payload, "an invoke payload");
    assertNoJargon(payload, "an invoke payload");
  }
}

async function waitForAppReady() {
  await until(`!!document.querySelector('[data-testid="details-panel-toggle"]')`);
  await until(`!!document.querySelector('[data-testid="change-journal"]')`);
  await until(`document.querySelector('[data-testid="lifecycle-open"]') && !document.querySelector('[data-testid="lifecycle-open"]').disabled`);
}
const revisionExpression = `(() => { const t = document.querySelector('[data-testid="report-brain"]')?.textContent ?? ''; const m = /révision (\\d+)/.exec(t); return m ? Number(m[1]) : -1; })()`;
const currentRevision = () => evaluate(revisionExpression);
const uiModeAttribute = () =>
  evaluate(`document.querySelector('[data-testid="application-mode"]')?.getAttribute('data-application-mode') ?? null`);
const uiModeText = () => evaluate(`document.querySelector('[data-testid="application-mode"]')?.textContent ?? ''`);
const uiSummaryText = () => evaluate(`document.querySelector('[data-testid="change-summary"]')?.textContent ?? ''`);
const uiSummary = async () =>
  JSON.parse(await evaluate(`document.querySelector('[data-testid="change-summary"]')?.getAttribute('data-summary') ?? 'null'`));

/**
 * One real click on Actualiser (or Reconstruire). Resolves once the product has
 * answered `expected` build call(s) and settled: the answers themselves, the
 * summary and the discreet mode label the UI shows, and the revision it reports.
 */
async function lifecycle(testid, expected = 1) {
  const from = await probeCount();
  await activate(`[data-testid="${testid}"]`);
  const waitStart = Date.now();
  while (wireCalls.length < from + expected) {
    if (Date.now() - waitStart > 120000) {
      console.error(
        "DIAGNOSTIC lifecycle:",
        JSON.stringify({
          testid,
          expected,
          seen: wireCalls.length - from,
          buttonDisabled: await evaluate(`document.querySelector('[data-testid="${testid}"]')?.disabled ?? null`),
          body: await evaluate(`document.body.innerText.slice(0, 400)`),
        }),
      );
      throw new Error(`timeout waiting for ${expected} ${testid} answer(s) on the wire`);
    }
    await pause(100);
  }
  await until(`!document.querySelector('[data-testid="lifecycle-open"]').disabled`);
  await pause(500);
  const calls = await probeCalls(from);
  for (const call of calls) assert(call.ok, `the product refused a ${call.command}`);
  return {
    calls,
    command: calls[0].command,
    revision: await currentRevision(),
    mode: await uiModeAttribute(),
    modeText: await uiModeText(),
    summaryText: await uiSummaryText(),
    summary: await uiSummary(),
  };
}
const refresh = (expected = 1) => lifecycle("lifecycle-refresh", expected);
const rebuild = () => lifecycle("lifecycle-rebuild");

function assertCounters(summary, expected, where) {
  const actual = {
    created: summary.created,
    modified: summary.modified,
    renamed: summary.renamed,
    moved: summary.moved,
    deleted: summary.deleted,
    total: summary.total,
  };
  assert.deepEqual(actual, { created: 0, modified: 0, renamed: 0, moved: 0, deleted: 0, total: 0, ...expected }, where);
}
async function resolve(id, relativePath) {
  const reference = await invoke("map_resolve_node", { brainId: id, relativePath });
  assert(reference, `no node resolves at ${relativePath}`);
  return reference.nodeId;
}
const resolveOrNull = async (id, relativePath) => {
  try {
    const reference = await invoke("map_resolve_node", { brainId: id, relativePath });
    return reference ? reference.nodeId : null;
  } catch {
    return null;
  }
};

// ---- the real panels ---------------------------------------------------------
async function openJournal() {
  const open = await evaluate(`document.querySelector('[data-testid="journal-toggle"]').getAttribute('aria-expanded') === 'true'`);
  if (!open) await activate('[data-testid="journal-toggle"]');
  await until(`!!document.querySelector('[data-testid="journal-total"]')`);
}
const uiEvents = () =>
  evaluate(`[...document.querySelectorAll('[data-testid="journal-event"]')].map((e) => ({
    eventId: Number(e.getAttribute('data-event-id')),
    nature: e.getAttribute('data-nature'),
    nodeId: Number(e.getAttribute('data-node-id')),
    present: e.getAttribute('data-node-present') === 'true',
    seen: e.getAttribute('data-seen') === 'true',
  }))`);
const uiUnseenTotal = () =>
  evaluate(`Number(document.querySelector('[data-testid="journal-unseen-total"]')?.getAttribute('data-unseen-total') ?? -1)`);
const waitUnseen = (n) =>
  until(`Number(document.querySelector('[data-testid="journal-unseen-total"]')?.getAttribute('data-unseen-total') ?? -1) === ${n}`);
async function apiPage(id) {
  const page = await invoke("map_change_journal", { brainId: id, natures: [], after: null, limit: 50 });
  assert.equal(page.brainId, id, "a journal page names the brain it was read from");
  return page;
}
const flagsOf = (page) => page.items.map((e) => [e.eventId, e.seen]);
const natureCounts = (events) => {
  const counts = {};
  for (const e of events) counts[e.nature] = (counts[e.nature] ?? 0) + 1;
  return counts;
};
const nodeBadge = () =>
  evaluate(`document.querySelector('[data-testid="node-state-badge"]')?.getAttribute('data-state') ?? null`);
const waitNodeBadge = (state) =>
  until(`document.querySelector('[data-testid="node-state-badge"]')?.getAttribute('data-state') === ${JSON.stringify(state)}`, 30000);
async function selectViaJournal(nodeId) {
  await openJournal();
  const selector = `[data-testid="journal-event"][data-node-id="${nodeId}"] [data-testid="journal-select"]`;
  await until(`!!document.querySelector(${JSON.stringify(selector)})`);
  await activate(selector);
  await until(`!!document.querySelector('[data-testid="node-state-badge"]')`);
}
async function markAllThroughThePanel() {
  await openJournal();
  await activate('[data-testid="journal-mark-all"]');
  await until(`!!document.querySelector('[data-testid="journal-mark-all-confirm"]')`);
  await activate('[data-testid="journal-mark-all-confirm-yes"]');
  await waitUnseen(0);
}

// ---- the real filter panel ---------------------------------------------------
async function click(selector) {
  const box = await evaluate(`(() => {
    const e = document.querySelector(${JSON.stringify(selector)});
    if (!e) return null;
    e.scrollIntoView({ block: "center" });
    const r = e.getBoundingClientRect();
    return { x: r.x + r.width / 2, y: r.y + r.height / 2, disabled: !!e.disabled };
  })()`);
  assert(box, `click: selector not found — ${selector}`);
  assert(!box.disabled, `click: element is disabled — ${selector}`);
  await pause(80);
  await send("Input.dispatchMouseEvent", { type: "mouseMoved", x: box.x, y: box.y });
  await send("Input.dispatchMouseEvent", { type: "mousePressed", x: box.x, y: box.y, button: "left", clickCount: 1 });
  await send("Input.dispatchMouseEvent", { type: "mouseReleased", x: box.x, y: box.y, button: "left", clickCount: 1 });
  await pause(150);
}
const setState = (state) => click(`[data-testid="filter-state-${state}"]`);
const uiFilterTotal = () =>
  evaluate(`(() => { const e = document.querySelector('[data-testid="filter-count"]'); return e ? Number(e.getAttribute('data-total')) : -1; })()`);
const waitFilterTotal = (n, limit = 30000) =>
  until(`(() => { const e = document.querySelector('[data-testid="filter-count"]'); return !!e && Number(e.getAttribute('data-total')) === ${n}; })()`, limit);
const filterMatchNodeIds = () =>
  evaluate(`[...document.querySelectorAll('[data-testid="filter-result"]')].filter((e) => e.getAttribute('data-filter-role') === 'match').map((e) => Number(e.getAttribute('data-node-id')))`);
async function apiFiltered(id, state) {
  const view = await invoke("map_view", { brainId: id, after: null, filter: { state, kinds: [], availability: "ALL" } });
  return view.filtered;
}
async function withFilter(state, expectedIds) {
  await setState(state);
  await waitFilterTotal(expectedIds.length);
  const shown = (await filterMatchNodeIds()).slice().sort((a, b) => a - b);
  assert.deepEqual(shown, expectedIds.slice().sort((a, b) => a - b), `the ${state} filter shows exactly the expected nodes`);
  const api = await apiFiltered(brainId, state);
  assert.equal(api.filteredTotal, expectedIds.length, `the backend agrees on ${state}`);
  assert.deepEqual(api.filterMatchIds.slice().sort((a, b) => a - b), expectedIds.slice().sort((a, b) => a - b));
}
async function resetFilter() {
  await click('[data-testid="filter-reset"]');
  await until(`document.querySelector('[data-testid="filter-panel"]').getAttribute('data-active') === 'false'`);
}

const results = {};
await waitForAppReady();

async function focusBrain(id) {
  await activate(`[data-testid="composition-chip-${id}"]`);
  await until(`document.querySelector('[data-testid="composition-chip-${id}"]')?.getAttribute('aria-current') === 'true'`);
  await pause(500);
}
const indexIdOf = async (id) => (await invoke("map_open", { brainId: id })).indexId;

if (phase === 1) {
  // ---- 1 — first Actualiser: the baseline, by a full publication --------------
  const first = await refresh();
  results.firstIsBaselineFull =
    first.command === "map_refresh" &&
    first.mode === "BASELINE_FULL" &&
    first.summary.baselineEstablished === true &&
    first.summary.total === 0 &&
    /Première indexation/.test(first.modeText) &&
    /Référence établie/.test(first.summaryText);
  assert(results.firstIsBaselineFull, "the first Actualiser lays the baseline, in full, and says so");
  await openJournal();
  await waitUnseen(0);
  results.firstInventsNoEvent = (await uiEvents()).length === 0;
  assert(results.firstInventsNoEvent, "no CREATED event is invented at the first build");
  const overview = await invoke("map_open", { brainId });
  assert.equal(overview.schemaVersion, 6);
  results.schemaVersion = overview.schemaVersion;
  const baselineRevision = overview.revision;
  assert.equal(first.revision, baselineRevision);
  const indexId = overview.indexId;

  // ---- 2 — an unchanged Actualiser: incremental, quiet, same revision ----------
  const quiet = await refresh();
  results.unchangedIsIncrementalNoOp =
    quiet.command === "map_refresh" &&
    quiet.mode === "INCREMENTAL" &&
    quiet.summary.baselineEstablished === false &&
    quiet.summary.total === 0 &&
    quiet.revision === baselineRevision &&
    (await indexIdOf(brainId)) === indexId &&
    quiet.summaryText === "Aucun changement détecté." &&
    /Mise à jour incrémentale/.test(quiet.modeText);
  assert(results.unchangedIsIncrementalNoOp, "an unchanged Actualiser is an incremental no-op that keeps the revision");
  await waitUnseen(0);
  assert.equal((await uiEvents()).length, 0, "and no false mass creation");

  // ---- 3 — a batch of external mutations, ONE real Actualiser -------------------
  const renamedId = await resolve(brainId, "stable-0.txt");
  const movedId = await resolve(brainId, "stable-1.txt");
  const modifiedId = await resolve(brainId, "a-modifier.txt");
  const deletedId = await resolve(brainId, "a-supprimer.txt");
  const folderId = await resolve(brainId, "dossier");
  const nestedId = await resolve(brainId, "dossier/sous/profond.txt");
  await writeFile(join(root, "nouveau.txt"), "synthetique — objet cree\n", "utf8");
  await writeFile(join(root, "a-modifier.txt"), "synthetique — apres, plus long qu'avant\n", "utf8");
  await rm(join(root, "a-supprimer.txt"));
  await rename(join(root, "stable-0.txt"), join(root, "renomme-0.txt"));
  await rename(join(root, "stable-1.txt"), join(root, "vide", "stable-1.txt"));
  await mkdir(join(root, "neuf"));
  await writeFile(join(root, "neuf", "x.txt"), "synthetique — dans un dossier neuf\n", "utf8");
  const batch = await refresh();
  assertCounters(batch.summary, { created: 3, modified: 1, renamed: 1, moved: 1, deleted: 1, total: 7 }, "batch counters (UI)");
  results.batchIsIncrementalWithExactSummary =
    batch.mode === "INCREMENTAL" &&
    batch.revision === baselineRevision + 1 &&
    batch.summaryText ===
      "7 changement(s) détecté(s) : 3 créé(s) · 1 modifié(s) · 1 renommé(s) · 1 déplacé(s) · 1 supprimé(s)" &&
    (await invoke("map_open", { brainId })).revision === baselineRevision + 1;
  assert(results.batchIsIncrementalWithExactSummary, "one incremental Actualiser: the exact summary, exactly one new revision");
  assert.equal(await resolve(brainId, "renomme-0.txt"), renamedId, "a same-volume rename keeps the nodeId");
  assert.equal(await resolve(brainId, "vide/stable-1.txt"), movedId, "a same-volume move keeps the nodeId");
  assert.equal(await resolve(brainId, "a-modifier.txt"), modifiedId);
  assert.equal(await resolveOrNull(brainId, "a-supprimer.txt"), null, "the deleted file no longer resolves");
  results.identitiesKeptThroughIncrementalRefresh = true;

  // ---- 4 — the journal, read through the real panel ----------------------------
  await openJournal();
  await waitUnseen(7);
  let events = await uiEvents();
  let api = await apiPage(brainId);
  assert.equal(events.length, 7);
  assert.deepEqual(natureCounts(events), { CREATED: 3, MODIFIED: 1, RENAMED: 1, MOVED: 1, DELETED: 1 });
  assert.deepEqual(flagsOf(api), events.map((e) => [e.eventId, e.seen]), "the panel is the backend's own page");
  const deletedEvent = events.find((e) => e.nature === "DELETED");
  results.journalMatchesTheBatch =
    events.every((e) => !e.seen) &&
    deletedEvent.nodeId === deletedId &&
    !deletedEvent.present &&
    events.find((e) => e.nature === "RENAMED").nodeId === renamedId &&
    events.find((e) => e.nature === "MOVED").nodeId === movedId &&
    events.find((e) => e.nature === "MODIFIED").nodeId === modifiedId;
  assert(results.journalMatchesTheBatch, "every event names the node it happened to; the deleted one is history only");

  // ---- 5 — NEW / UNSEEN through the real filter panel --------------------------
  const nouveauId = await resolve(brainId, "nouveau.txt");
  const neufId = await resolve(brainId, "neuf");
  const xId = await resolve(brainId, "neuf/x.txt");
  await withFilter("NEW", [nouveauId, neufId, xId]);
  await withFilter("UNSEEN", [nouveauId, neufId, xId, modifiedId, renamedId, movedId]);
  results.filtersExactAfterIncrementalRefresh = true;
  await resetFilter();

  // ---- 6 — « Tout marquer vu », then a later change is unseen again -----------
  const totalBeforeMarkAll = (await apiPage(brainId)).total;
  await markAllThroughThePanel();
  await withFilter("UNSEEN", []);
  await resetFilter();
  assert.equal((await apiPage(brainId)).total, totalBeforeMarkAll, "no event was removed");
  const afterMarkAllRevision = await currentRevision();
  const acknowledged = flagsOf(await apiPage(brainId));

  await writeFile(join(root, "nouveau.txt"), "synthetique — objet cree, puis modifie, donc plus long\n", "utf8");
  await writeFile(join(root, "apres.txt"), "synthetique — apres le tout marquer vu\n", "utf8");
  const later = await refresh();
  assertCounters(later.summary, { created: 1, modified: 1, total: 2 }, "post mark-all counters");
  assert.equal(later.mode, "INCREMENTAL");
  assert.equal(later.revision, afterMarkAllRevision + 1);
  await waitUnseen(2);
  events = await uiEvents();
  api = await apiPage(brainId);
  const apresId = await resolve(brainId, "apres.txt");
  results.changeAfterSeenReappears =
    events.length === 9 &&
    events.filter((e) => !e.seen).length === 2 &&
    events.slice(2).every((e) => e.seen) &&
    JSON.stringify(flagsOf(api).slice(2)) === JSON.stringify(acknowledged);
  assert(results.changeAfterSeenReappears, "only the two new events are unseen; the earlier ones keep their acknowledgement");
  await withFilter("NEW", [apresId]);
  await withFilter("UNSEEN", [nouveauId, apresId]);
  await resetFilter();

  // ---- 7 — an element marked seen, then changed again ----------------------------
  await selectViaJournal(nouveauId);
  await activate('[data-testid="node-mark-seen"]');
  await waitNodeBadge("seen");
  await waitUnseen(1);
  await writeFile(join(root, "nouveau.txt"), "synthetique — encore modifie, encore plus long qu'avant\n", "utf8");
  const again = await refresh();
  assertCounters(again.summary, { modified: 1, total: 1 }, "element changed again");
  assert.equal(again.mode, "INCREMENTAL");
  await waitUnseen(2);
  await selectViaJournal(nouveauId);
  await waitNodeBadge("unseen");
  results.seenElementChangedAgainIsUnseen = (await nodeBadge()) === "unseen";
  assert(results.seenElementChangedAgainIsUnseen, "an acknowledged element that changes again is unseen again (and not new)");

  // ---- 8 — a whole folder renamed: the descendants follow ----------------------
  await rename(join(root, "dossier"), join(root, "dossier-renomme"));
  const folder = await refresh();
  assertCounters(folder.summary, { renamed: 1, total: 1 }, "folder rename counters");
  assert.equal(folder.mode, "INCREMENTAL");
  assert.equal(await resolve(brainId, "dossier-renomme"), folderId);
  assert.equal(await resolve(brainId, "dossier-renomme/sous/profond.txt"), nestedId);
  assert.equal(await resolveOrNull(brainId, "dossier/sous/profond.txt"), null);
  results.folderRenameKeepsDescendants = true;

  // ---- 9 — Reconstruire: an explicit full replacement, history intact --------------
  const beforeRebuild = await apiPage(brainId);
  const flagsBeforeRebuild = flagsOf(beforeRebuild);
  const revisionBeforeRebuild = await currentRevision();
  const rebuilt = await rebuild();
  results.rebuildIsExplicitFull =
    rebuilt.command === "map_rebuild" &&
    rebuilt.mode === "EXPLICIT_REBUILD_FULL" &&
    rebuilt.summary.total === 0 &&
    rebuilt.summary.baselineEstablished === false &&
    rebuilt.revision === revisionBeforeRebuild + 1 &&
    /Reconstruction complète/.test(rebuilt.modeText);
  assert(results.rebuildIsExplicitFull, "Reconstruire stays an explicit full replacement");
  const afterRebuild = await apiPage(brainId);
  results.rebuildKeepsJournalAndSeenState =
    JSON.stringify(flagsOf(afterRebuild)) === JSON.stringify(flagsBeforeRebuild) &&
    afterRebuild.unseenTotal === beforeRebuild.unseenTotal &&
    (await resolve(brainId, "dossier-renomme/sous/profond.txt")) === nestedId;
  assert(results.rebuildKeepsJournalAndSeenState, "a rebuild of an unchanged tree keeps journal, seen state and ids");

  // ---- 10 — and the next Actualiser is incremental again ---------------------------
  await writeFile(join(root, "apres-reconstruction.txt"), "synthetique — apres la reconstruction\n", "utf8");
  const afterRebuildRefresh = await refresh();
  assertCounters(afterRebuildRefresh.summary, { created: 1, total: 1 }, "after rebuild");
  results.incrementalAgainAfterRebuild = afterRebuildRefresh.mode === "INCREMENTAL";
  assert(results.incrementalAgainAfterRebuild);

  // What phase 2 must find again.
  const firstPage = await apiPage(brainId);
  const snapshotOverview = await invoke("map_open", { brainId });
  results.firstBrainSnapshot = {
    flags: flagsOf(firstPage),
    unseenTotal: firstPage.unseenTotal,
    total: firstPage.total,
    revision: snapshotOverview.revision,
    indexId: snapshotOverview.indexId,
    nestedId,
    nouveauId,
  };
  assert.equal(snapshotOverview.indexId, indexId, "one Index, from the baseline to now, whatever the paths taken");

  // ---- 11 — a second brain, refreshed alongside: nothing shared ------------------
  await activate('[data-testid="composition-add-trigger"]');
  await until(`!!document.querySelector('[data-testid="composition-add-item-${secondBrainId}"]')`);
  await activate(`[data-testid="composition-add-item-${secondBrainId}"]`);
  await until(`!!document.querySelector('[data-testid="composition-chip-${secondBrainId}"]')`);
  await focusBrain(secondBrainId);
  // Both brains are now composed: one Actualiser answers for both.
  const both = await refresh(2);
  assert.equal(both.calls.length, 2);
  results.secondBrainBaseline = both.mode === "BASELINE_FULL" && both.summary.baselineEstablished === true;
  assert(results.secondBrainBaseline, "the second brain lays its own baseline");
  await focusBrain(brainId);
  const firstAfterBoth = {
    mode: await uiModeAttribute(),
    summary: await uiSummary(),
    revision: await currentRevision(),
  };
  results.firstBrainQuietIncrementalBesideSecond =
    firstAfterBoth.mode === "INCREMENTAL" &&
    firstAfterBoth.summary.total === 0 &&
    firstAfterBoth.revision === results.firstBrainSnapshot.revision;
  assert(results.firstBrainQuietIncrementalBesideSecond, "the first brain stays a quiet incremental no-op");

  await writeFile(join(secondRoot, "b-nouveau.txt"), "synthetique b\n", "utf8");
  await focusBrain(secondBrainId);
  const bothAgain = await refresh(2);
  assertCounters(bothAgain.summary, { created: 1, total: 1 }, "second brain counters");
  assert.equal(bothAgain.mode, "INCREMENTAL");
  await focusBrain(brainId);
  const firstAfterSecond = await apiPage(brainId);
  results.firstBrainUntouchedBySecond =
    (await uiSummary()).total === 0 &&
    JSON.stringify(flagsOf(firstAfterSecond)) === JSON.stringify(results.firstBrainSnapshot.flags) &&
    (await apiPage(secondBrainId)).total === 1;
  assert(results.firstBrainUntouchedBySecond, "the second brain's change is in its own journal only");

  await assertConfidential();
  results.noAbsolutePathOrIdentityLeak = true;
} else {
  // ---- phase 2: after a REAL process restart ---------------------------------
  const before = JSON.parse(await readFile(join(proofRoot, "phase1.json"), "utf8"));
  const first = before.firstBrainSnapshot;
  await until(`${revisionExpression} >= 0`);
  await openJournal();

  // Backend truth, flag for flag; opening is not a refresh.
  const page = await apiPage(brainId);
  results.journalAndSeenStateIdentical =
    JSON.stringify(flagsOf(page)) === JSON.stringify(first.flags) &&
    page.unseenTotal === first.unseenTotal &&
    page.total === first.total;
  assert(results.journalAndSeenStateIdentical, "journal and acknowledgements survive the restart, flag for flag");
  const overview = await invoke("map_open", { brainId });
  results.indexIdentityAndRevisionKept =
    overview.indexId === first.indexId && overview.revision === first.revision && overview.sourceRead === false;
  assert(results.indexIdentityAndRevisionKept, "the same Index, the same revision, no source read");
  results.schemaVersion = overview.schemaVersion;
  assert.equal(overview.schemaVersion, 6);
  assert.equal(await resolve(brainId, "dossier-renomme/sous/profond.txt"), first.nestedId, "ids survive the restart");
  await waitUnseen(first.unseenTotal);
  assert.equal(await probeCount(), 0, "no build ran by itself at start-up");

  // A cold Actualiser: the Index is stamped, so it is incremental — and quiet.
  const cold = await refresh();
  results.coldRefreshIsIncrementalNoOp =
    cold.command === "map_refresh" &&
    cold.mode === "INCREMENTAL" &&
    cold.summary.total === 0 &&
    cold.revision === first.revision &&
    cold.summaryText === "Aucun changement détecté.";
  assert(results.coldRefreshIsIncrementalNoOp, "after a restart the first Actualiser is an incremental no-op");

  // One more change, applied incrementally on the restarted process.
  await writeFile(join(root, "apres-redemarrage.txt"), "synthetique — apres le redemarrage\n", "utf8");
  const next = await refresh();
  assertCounters(next.summary, { created: 1, total: 1 }, "after restart");
  results.changeAfterRestartIsIncremental = next.mode === "INCREMENTAL" && next.revision === first.revision + 1;
  assert(results.changeAfterRestartIsIncremental);
  await waitUnseen(first.unseenTotal + 1);
  const grown = await apiPage(brainId);
  assert.deepEqual(flagsOf(grown).slice(1), first.flags, "the earlier journal is intact under the new event");

  await assertConfidential();
  results.noAbsolutePathOrIdentityLeak = true;
}

await writeFile(join(proofRoot, `phase${phase}.json`), JSON.stringify(results));
console.log(JSON.stringify({ ok: true, phase }));

assert.equal(fatal.length, 0, `fatal page/console errors`);
await writeFile(join(proofRoot, `phase${phase}-fatal-count.json`), JSON.stringify(fatal.length));
ws.close();
